UPDATE "CEI2008" SET text = '<po>Un vasaio, impastando con fatica la terra molle,</po>
<po>plasma per il nostro uso ogni vaso.</po>
<po>Ma con il medesimo fango modella</po>
<po>i vasi che servono per usi nobili</po>
<po>e quelli per usi contrari, tutti allo stesso modo;</po>
<po>quale debba essere l''uso di ognuno di essi</po>
<po>lo giudica colui che lavora l''argilla.</po>', title1 = '', title2 = '', title3 = '', title_position = NULL WHERE "verseID" = 19810 AND text = 'Un vasaio, impastando con fatica la terra molle, plasma per il nostro uso ogni vaso. Ma con il medesimo fango modella i vasi che servono per usi nobili e quelli per usi contrari, tutti allo stesso modo; quale debba essere l''uso di ognuno di essi lo giudica colui che lavora l''argilla.' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '' AND bibleget_plain_text('<po>Un vasaio, impastando con fatica la terra molle,</po>
<po>plasma per il nostro uso ogni vaso.</po>
<po>Ma con il medesimo fango modella</po>
<po>i vasi che servono per usi nobili</po>
<po>e quelli per usi contrari, tutti allo stesso modo;</po>
<po>quale debba essere l''uso di ognuno di essi</po>
<po>lo giudica colui che lavora l''argilla.</po>') = text_plain;  -- Sap 15:7
UPDATE "CEI2008" SET text = '<po>Quindi, mal impiegando la fatica,</po>
<po>con il medesimo fango plasma un dio vano,</po>
