UPDATE "CEI2008" SET text = 'e gli disse: <i>Esci dalla tua terra e dalla tua gente e vieni nella terra che io ti indicherò</i>.', title1 = '', title2 = '', title3 = '', title_position = NULL WHERE "verseID" = 31174 AND text = 'e gli disse: Esci dalla tua terra e dalla tua gente e vieni nella terra che io ti indicherò.' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '' AND bibleget_plain_text('e gli disse: <i>Esci dalla tua terra e dalla tua gente e vieni nella terra che io ti indicherò</i>.') = text_plain;  -- At 7:3
