UPDATE "CEI2008" SET text = 'Questo Mosè, che essi avevano rinnegato dicendo: " <i>Chi ti ha costituito capo e giudice? </i>", proprio lui Dio mandò come capo e liberatore, per mezzo dell''angelo che gli era apparso nel roveto.', title1 = '', title2 = '', title3 = '', title_position = NULL WHERE "verseID" = 31206 AND text = 'Questo Mosè, che essi avevano rinnegato dicendo: " Chi ti ha costituito capo e giudice? ", proprio lui Dio mandò come capo e liberatore, per mezzo dell''angelo che gli era apparso nel roveto.' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '' AND bibleget_plain_text('Questo Mosè, che essi avevano rinnegato dicendo: " <i>Chi ti ha costituito capo e giudice? </i>", proprio lui Dio mandò come capo e liberatore, per mezzo dell''angelo che gli era apparso nel roveto.') = text_plain;  -- At 7:35
